package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.enums.ProductStatus; // Enum ကို Import လုပ်ရန်import com.digitalbase.ticketing.model.ClientProduct;import com.digitalbase.ticketing.repository.ClientProductRepository;import lombok.RequiredArgsConstructor;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.time.ZoneId;import java.time.temporal.ChronoUnit;import java.util.Arrays;import java.util.List;@Service@RequiredArgsConstructorpublic class SlaExpirationJobService {    private final ClientProductRepository clientProductRepository;    // Notification (သို့) Email ပို့ရန် Service ကို ဤနေရာတွင် Inject လုပ်ပါ    // ည ၁၂ နာရီတိုင်း အလိုအလျောက် အလုပ်လုပ်မည်//    @Scheduled(cron = "0 0 0 * * ?")    @Scheduled(fixedRate = 10000)    @Transactional    public void checkSlaExpirations() {        // 👈 [ပြင်ဆင်ချက် ၁] UPCOMING Plan များကိုပါ Database မှ တစ်ပါတည်း ဆွဲထုတ်ပါမည်        List<ProductStatus> workingStatuses = Arrays.asList(ProductStatus.ACTIVE, ProductStatus.EXPIRING_SOON, ProductStatus.UPCOMING);        List<ClientProduct> productsToCheck = clientProductRepository.findAllByStatusIn(workingStatuses);        LocalDate today = LocalDate.now();        for (ClientProduct cp : productsToCheck) {            // 🌟 [အသစ်ထပ်ဖြည့်ခြင်း] UPCOMING Plan များ စတင်မည့်ရက်ရောက်လျှင် ACTIVE အဖြစ် ပြောင်းပေးရန်            if (cp.getStatus() == ProductStatus.UPCOMING && cp.getPlanStartDate() != null) {                LocalDate startDate = cp.getPlanStartDate().atZone(ZoneId.systemDefault()).toLocalDate();                // စတင်မည့်ရက်သည် ယနေ့ (သို့မဟုတ်) ယနေ့ထက်ကျော်လွန်နေပြီဆိုလျှင်                if (!today.isBefore(startDate)) {                    cp.setStatus(ProductStatus.ACTIVE);                    clientProductRepository.save(cp);                    sendWarningNotification(cp, "Your renewed SLA Plan has officially started today.");                }                continue; // UPCOMING အဆင့်ဖြစ်နေသေးလျှင် အောက်က Expire ဖြစ်မည့်ရက်များကို ဆက်မစစ်တော့ဘဲ ကျော်သွားမည်            }            // ==========================================================            // အောက်ပိုင်းသည် သင်၏ မူလ Expiration Logic အတိုင်း ဆက်လက်ရှိနေပါမည်            // ==========================================================            if (cp.getPlanEndDate() == null) continue;            // Instant ကို LocalDate သို့ ပြောင်းလဲခြင်း            LocalDate endDate = cp.getPlanEndDate().atZone(ZoneId.systemDefault()).toLocalDate();            // ကျန်ရှိသော ရက်အရေအတွက် တွက်ချက်ခြင်း            long daysRemaining = ChronoUnit.DAYS.between(today, endDate);            if (daysRemaining <= 0) {                // 💡 အကြံပြုချက် - ဤနေရာတွင် DISABLED အစား ယခင်က ထပ်ဖြည့်ခဲ့သော EXPIRED ကို သုံးသင့်ပါသည်။                // (DISABLED သည် Admin မှ ကိုယ်တိုင် Rule ဖောက်ဖျက်၍ ပိတ်လိုက်သော အခြေအနေမျိုးအတွက်သာ သီးသန့်ထားသင့်ပါသည်)                cp.setStatus(ProductStatus.EXPIRED);                clientProductRepository.save(cp);                sendWarningNotification(cp, "Your SLA Plan has expired. You now have read-only access. Please upgrade your plan.");            } else if (daysRemaining <= 7 && cp.getStatus() == ProductStatus.ACTIVE) {                // ၇ ရက်နှင့်အောက် ရောက်သွားလျှင် EXPIRING_SOON အဖြစ် အလိုအလျောက် ပြောင်းလဲမည်                cp.setStatus(ProductStatus.EXPIRING_SOON);                clientProductRepository.save(cp);                sendWarningNotification(cp, "Reminder: Your SLA Plan expires in " + daysRemaining + " days. Please renew to avoid service interruption.");            } else if (daysRemaining == 3 || daysRemaining == 1) {                // ၃ ရက် သို့မဟုတ် ၁ ရက် လိုပါက Notification သာ ထပ်ပို့မည်                sendWarningNotification(cp, "Urgent: Your SLA Plan expires in " + daysRemaining + " days. Renew now to keep your access.");            }        }    }    private void sendWarningNotification(ClientProduct cp, String message) {        // ဤနေရာတွင် Customer ထံသို့ Email ပို့ခြင်း (သို့မဟုတ်) In-App Notification (ခေါင်းလောင်းလေး) ထဲသို့ စာဝင်သွားအောင် ရေးသားပါ        System.out.println("Sending to " + cp.getUser().getEmail() + " : " + message);    }}